	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "cotizacion_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"consulta_id" integer NOT NULL,
