	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" integer NOT NULL,
	CONSTRAINT "cotizacion_estado_valido" CHECK ("cotizacion"."estado" in ('enviada', 'reemplazada', 'aceptada')),
	CONSTRAINT "cotizacion_descuento_valido" CHECK ("cotizacion"."descuento" >= 0),
	CONSTRAINT "cotizacion_total_valido" CHECK ("cotizacion"."total" = "cotizacion"."subtotal" - "cotizacion"."descuento" and "cotizacion"."total" >= 0),
	CONSTRAINT "cotizacion_adelanto_valido" CHECK ("cotizacion"."adelanto_sugerido" >= 0 and "cotizacion"."adelanto_sugerido" <= "cotizacion"."total"),
	CONSTRAINT "cotizacion_version_valida" CHECK ("cotizacion"."version" >= 1)
);
